<?php
namespace Dth\Crm\Services; use Dth\Crm\Models\Customer; use Dth\Crm\Support\{CodeGenerator,Normalizer};
final class CustomerImportService {public function __construct(private CodeGenerator $codes,private Normalizer $n){} public function importRows(iterable $rows):array{$ok=0;$errors=[];foreach($rows as $i=>$row){try{$email=$this->n->email($row['email']??null);$phone=$this->n->phone($row['phone']??null);$q=Customer::query();$c=$email?(clone $q)->where('normalized_email',$email)->first():null;if(!$c&&$phone)$c=(clone $q)->where('normalized_phone',$phone)->first();$data=['customer_type'=>$row['customer_type']??'personal','display_name'=>$row['display_name']??$row['name']??$email??$phone??'Customer','email'=>$row['email']??null,'normalized_email'=>$email,'phone'=>$row['phone']??null,'normalized_phone'=>$phone,'status'=>$row['status']??'potential','acquisition_source'=>$row['acquisition_source']??'import'];if($c)$c->update(array_filter($data,fn($v)=>$v!==null));else Customer::create($data+['customer_code'=>$this->codes->make('CUS')]);$ok++;}catch(\Throwable $e){$errors[]=['row'=>$i,'message'=>$e->getMessage()];}}return ['imported'=>$ok,'errors'=>$errors];}}
